export function merge(a, b) {
  const all = [...(a || []), ...(b || [])]
    .map(({ start, end }) => ({ start, end }))
    .sort((x, y) => x.start - y.start || x.end - y.end);

  const result = [];
  for (const iv of all) {
    const last = result[result.length - 1];
    if (last && iv.start <= last.end) {
      if (iv.end > last.end) last.end = iv.end;
    } else {
      result.push(iv);
    }
  }
  return result;
}
